"""Pure synthetic analysis tests: no games, training, teacher or benchmarks."""
import copy, importlib.util, unittest
from pathlib import Path
import numpy as np
spec=importlib.util.spec_from_file_location('analysis',Path(__file__).with_name('a100-strength-analysis.py'))
a=importlib.util.module_from_spec(spec);spec.loader.exec_module(a)
def book():return {'splits':{'arena':[{'source_game':str(i),'opening':{'moves':['e2e4']}}for i in range(48)]}}
def result(scores=(1,1),cap=False):
    return {'games':[{'opening_pair':r,'candidate_color':c,'opening':['e2e4'],'score':scores[k], 'termination':'max_plies'if cap else 'checkmate'}for r in range(48)for k,c in enumerate(('white','black'))]}
class Tests(unittest.TestCase):
    def test_pairing_by_keys_survives_order(self):
        r=result((1,0));r['games'].reverse();s,c=a.block_scores(r,book());np.testing.assert_equal(s[:,0],1);np.testing.assert_equal(s[:,1],0)
    def test_duplicate_pair_rejected(self):
        r=result();r['games'][-1]=r['games'][0]
        with self.assertRaises(ValueError):a.block_scores(r,book())
    def test_partial_rejected(self):
        r=result();r['games'].pop()
        with self.assertRaises(ValueError):a.block_scores(r,book())
    def test_root_mismatch_rejected(self):
        r=result();r['games'][0]['opening']=['d2d4']
        with self.assertRaises(ValueError):a.block_scores(r,book())
    def test_unknown_cap_must_half(self):
        with self.assertRaises(ValueError):a.block_scores(result((1,1),True),book())
    def test_equal_reference_delta_exact_zero(self):
        r=a.assess_seed(result(),result((.5,0)),result((.5,0)),book(),20261105)
        self.assertEqual(r['sf_paired_delta']['ci_adjusted_98_75'],[0,0]);self.assertFalse(r['strength_pass'])
    def test_identical_colour_blocks_no_individual_resampling(self):
        r=a.assess_seed(result((1,0)),result((1,0)),result((0,0)),book(),20261105)
        self.assertEqual(r['direct']['ci_adjusted_98_75'],[.5,.5])
    def test_large_signal_pass(self):
        r=a.assess_seed(result(),result(),result((0,0)),book(),20261105);self.assertTrue(r['strength_pass'])
    def test_caps_adversarial_not_fake_draw(self):
        r=a.assess_seed(result(),result((.5,.5),True),result((0,0)),book(),20261105)
        self.assertEqual(r['sf_delta_adversarial_caps']['mean'],0);self.assertFalse(r['strength_pass'])
    def test_repeated_analysis_bitwise(self):
        args=(result(),result((1,.5)),result((0,.5)),book(),20261106)
        self.assertEqual(a.assess_seed(*args),a.assess_seed(*args))
